INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('12e661ac-582e-4c7b-8899-2ac42118bf80', 'a1a1a1a1-3030-4000-8000-000000000001', 16, 'Dia 16 — Valores', 'Semana 3: Reconstruir', '{"pch": "Onde est\u00e1 o teu tesouro\u2026 a\u00ed est\u00e1 o teu cora\u00e7\u00e3o. O que voc\u00ea valoriza define quem voc\u00ea \u00e9.", "verse": "Mt 6,21", "lectio": "Leia Mt 6,19-24. Tesouro no c\u00e9u vs. tesouro na terra.", "practice": "Liste seus 5 valores mais importantes. Veja se sua vida reflete isso.", "question": "Quais s\u00e3o seus 3 valores inegoci\u00e1veis?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;